// @vegastack onboarding-01@0.9.1 sha256-SAEz9JYq6qc3+4yxo4T89xVqfgh9lBXkUuuSD1CjG0s=

"use client";

import * as React from "react";
import { Bot, CreditCard, Mail, Plug, Users } from "lucide-react";

import {
  OnboardingChecklist,
  OnboardingChecklistItem,
} from "@/components/ui/onboarding-checklist";

interface Step {
  id: string;
  label: string;
  icon: React.ReactNode;
  done: boolean;
}

const STEPS: Step[] = [
  {
    id: "workspace",
    label: "Name your workspace",
    icon: <Users />,
    done: true,
  },
  { id: "email", label: "Connect an inbox", icon: <Mail />, done: true },
  { id: "agent", label: "Create your first agent", icon: <Bot />, done: false },
  {
    id: "integration",
    label: "Install an integration",
    icon: <Plug />,
    done: false,
  },
  {
    id: "billing",
    label: "Add a payment method",
    icon: <CreditCard />,
    done: false,
  },
];

/**
 * The checklist itself: `OnboardingChecklist` over five sample steps, with the host owning `done`
 * exactly as the component's contract requires. Clicking a step marks it complete here; in a real
 * app that call is the one that records the step server-side.
 *
 * @example
 * <GettingStarted />
 */
export function GettingStarted() {
  const [steps, setSteps] = React.useState(STEPS);
  const done = steps.filter((step) => step.done).length;

  return (
    <OnboardingChecklist
      title="Getting started"
      done={done}
      total={steps.length}
    >
      {steps.map((step) => (
        <OnboardingChecklistItem
          key={step.id}
          icon={step.icon}
          done={step.done}
          onClick={() =>
            setSteps((previous) =>
              previous.map((candidate) =>
                candidate.id === step.id
                  ? { ...candidate, done: true }
                  : candidate,
              ),
            )
          }
        >
          {step.label}
        </OnboardingChecklistItem>
      ))}
    </OnboardingChecklist>
  );
}

// @vegastack onboarding-01@0.9.1 sha256-SAEz9JYq6qc3+4yxo4T89xVqfgh9lBXkUuuSD1CjG0s=

import { ArrowRight, BookOpen, MessagesSquare } from "lucide-react";

import { GettingStarted } from "./components/getting-started";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

const next = [
  {
    title: "Read the quickstart",
    description: "Ten minutes from an empty workspace to a running agent.",
    icon: BookOpen,
  },
  {
    title: "Talk to us",
    description: "A setup call with the team that builds Acme.",
    icon: MessagesSquare,
  },
];

/**
 * `onboarding-01` — the first-run starter page: the getting-started checklist beside two
 * what-is-next cards.
 *
 * @example
 * // app/welcome/page.tsx, straight after `shadcn add @vegastack/onboarding-01`
 * export { default } from "./page";
 */
export default function Page() {
  return (
    <div className="mx-auto flex min-h-svh w-full max-w-5xl flex-col gap-8 p-4 md:p-6">
      <div>
        <h1 className="text-xl font-semibold">Welcome to Acme</h1>
        <p className="text-sm text-muted-foreground">
          Five short steps and your workspace is doing real work.
        </p>
      </div>

      <div className="grid gap-4 md:grid-cols-[minmax(0,20rem)_minmax(0,1fr)]">
        <GettingStarted />
        <div className="grid gap-4 sm:grid-cols-2 md:grid-cols-1 lg:grid-cols-2">
          {next.map((item) => (
            <Card key={item.title}>
              <CardHeader>
                <item.icon className="size-5 text-muted-foreground" />
                <CardTitle>{item.title}</CardTitle>
                <CardDescription>{item.description}</CardDescription>
              </CardHeader>
              <CardContent>
                <Button variant="outline" size="sm">
                  Open
                  <ArrowRight />
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </div>
  );
}
